// Generate src/shared/api.d.ts from the engine's OpenAPI snapshot (../engine/openapi.json).
//
//   node scripts/gen-api.mjs           write the file
//   node scripts/gen-api.mjs --check   exit 1 when the committed file differs (drift test)
import { readFile, writeFile } from "node:fs/promises";
import openapiTS, { astToString } from "openapi-typescript";

const source = new URL("../../engine/openapi.json", import.meta.url);
const target = new URL("../src/shared/api.d.ts", import.meta.url);
const header =
  "// Generated by app/scripts/gen-api.mjs from engine/openapi.json (npm run gen:api).\n" +
  "// Do not edit: regenerate after `python -m nazeer_engine --dump-openapi openapi.json`.\n\n";

const generated = header + astToString(await openapiTS(source));
const normalize = (text) => text.replace(/\r\n/g, "\n");

if (process.argv.includes("--check")) {
  const current = await readFile(target, "utf8").catch(() => "");
  if (normalize(current) !== normalize(generated)) {
    console.error("src/shared/api.d.ts is stale: run `npm run gen:api`");
    process.exit(1);
  }
  console.log("src/shared/api.d.ts is up to date with engine/openapi.json");
} else {
  await writeFile(target, generated, "utf8");
  console.log("wrote src/shared/api.d.ts");
}
